-- Product details seed (draft copy, Epic 10 enhancement). Idempotent: re-running updates the rows.
-- Run after 0005_product_details.sql. Content is placeholder copy for the demo catalogue and should be
-- reviewed (weights, purities and stone details are illustrative, not measured).

on conflict (product_id) do update set
  description       = excluded.description,
  highlights        = excluded.highlights,
  material          = excluded.material,
  purity            = excluded.purity,
  weight_grams      = excluded.weight_grams,
  stone             = excluded.stone,
  dimensions        = excluded.dimensions,
  care_instructions = excluded.care_instructions,
  updated_at        = now();
